import React, { CSSProperties, PropsWithChildren } from "react";
import { spacingToTokenValue } from "../../lib/utils";
import {
  AlignItems,
  FlexDirection,
  JustifyContent,
  Spacing,
} from "../helperTypes";
import { CommonProps } from "../helperTypes";
import useDeprecatedProps from "../../lib/hooks/useDeprecatedProps";

type DeprecatedProps = {
  /** @deprecated use "gap" prop */
  childrenStyle?: CSSProperties;
  /** @deprecated use "gap" prop */
  spacing?: Spacing;
};

type Props = PropsWithChildren<{
  /**
   * Defines the `align-items` style property.
   * @default stretch
   */
  alignItems?: AlignItems;
  /**
   * Defines the `flex-direction` style property.
   * @default row
   */
  direction?: FlexDirection;
  /**
   * Defines the `justify-content` style property.
   * @default start
   */
  justify?: JustifyContent;
  /**
   * Defines the `position` style property.
   * @default static
   */
  position?: "absolute" | "relative" | "static";
  /**
   * Defines the `gap` style property.
   */
  gap?: Spacing;
  /**
   * Defines the `flex-wrap` style property.
   * @default false
   */
  wrap?: boolean;
}>;

export type FlexProps = Props & DeprecatedProps & CommonProps;

const getGap = (
  spacing: Spacing | undefined,
  negative: boolean = false
): string | undefined => {
  if (!spacing) return undefined;
  const value = spacingToTokenValue(spacing);
  return value ? `calc(${negative ? "-" : ""}${value}/2)` : undefined;
};

const getFlexPropertyValue = (propValue: string): string => {
  switch (propValue) {
    case "start":
      return "flex-start";
    case "end":
      return "flex-end";
    default:
      return propValue;
  }
};

const extractStylesFromProps = (props: FlexProps): [CSSProperties, any] => {
  const {
    position,
    direction,
    wrap,
    justify,
    alignItems,
    spacing,
    style,
    gap,
    ...rest
  } = props;

  const margin = spacing ? getGap(spacing, true) : undefined;
  const gapStyle = gap ? spacingToTokenValue(gap) : undefined;
  return [
    {
      display: "flex",
      position: position || "static",
      boxSizing: "border-box",
      flexDirection: direction || "row",
      flexWrap: wrap ? "wrap" : "nowrap",
      justifyContent: getFlexPropertyValue(justify || "start"),
      alignItems: getFlexPropertyValue(alignItems || "stretch"),
      ...(margin !== undefined && { margin }),
      ...(gapStyle !== undefined && { gap: gapStyle }),
      ...style,
    },
    rest,
  ];
};

const getStyleForChildren = (props: FlexProps): CSSProperties => {
  if (!props.spacing) return {};
  const padding = getGap(props.spacing);
  if (!padding) return {};
  return { padding };
};

const Flex = (props: FlexProps) => {
  const { className, children, childrenStyle, ...restProps } = props;
  useDeprecatedProps(
    "Flex",
    {
      spacing: "gap",
      childrenStyle: "gap",
    },
    props
  );
  const [style, rest] = extractStylesFromProps(restProps);

  return (
    <div className={className} style={style} {...rest}>
      {React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) {
          return null;
        }
        if (child.type === React.Fragment) {
          console.warn(
            "The Flex component doesn't accept a Fragment as a child. Consider providing an array instead."
          );
        }
        return !restProps.spacing ? (
          child
        ) : (
          <div style={{ ...getStyleForChildren(restProps), ...childrenStyle }}>
            {child}
          </div>
        );
      })}
    </div>
  );
};

export default Flex;
